from typing import List

class Solution:
    def missingNumber(self, nums: List[int]) -> int:
        n = len(nums)
        for target in range(n + 1):
            found = False
            for x in nums:
                if x == target:
                    found = True
                    break
            if not found:
                return target
        return -1

